            return inputVector.z > 0.0f ? Vector3.forward : Vector3.back;
        else
            return inputVector.x > 0.0f ? Vector3.right : Vector3.left;
    }
	private void StartIceFloor() {
        PlayerWork.isPlayerInputActive = false;
        AudioManager.Instance.PlaySe(AK.EVENTS.S_FI400, null);

        IceFloorState = IceFloorStateType.Slip;
        IceSlidingLevel = 1;
        IsIceSlope = false;
        IceFloorStopTime = 0.0f;
        IceSlidingSpeed = DataManager.GetFieldCommonParam(ParamIndx.IceFloorSpdLv1);
        IceFloorStartGridCenterPos = Vec2ToVec3Position(GridToPosition(oldGridPosition), worldPosition.y);

        float targetYaw = (float)Math.Atan2(IceFloorDirection.x, IceFloorDirection.z) * Mathf.Rad2Deg;
        IceSlidingRotate.FloatMove.EaseFunc = FieldFloatMove.EaseInOutSin;
        IceSlidingRotate.SetObjectEntity(this);
        IceSlidingRotate.MoveTime(targetYaw, 0.2f);

        IceSlopeDownMove.FloatMove.EaseFunc = FieldFloatMove.EaseInOutSin;
        IceSlopeDownMove.IgnoreY = true;
        IceSlopeDownMove.SetObjectEntity(this);

        Vector3 pos = worldPosition;
        int axis = IceFloorDirection.x != 0.0f ? 2 : 0;
        pos[axis] = IceFloorStartGridCenterPos[axis];

        float groundNear = CollisionUtility.CollideGround(pos - IceFloorDirection * 0.15f, 30.0f, Layer.Ground);
        float groundFar = CollisionUtility.CollideGround(pos - IceFloorDirection * 0.25f, 30.0f, Layer.Ground);
        float diff = groundFar - groundNear;
        if (diff * diff > 0.001f * 0.001f)
            IsIceSlope = true;

        PlayIdle();
        nextSequence = SequenceID.IceFloor;
    }
	private void EndIceFloor() {
