                float speed = UpdateIceSpeed(deltaTime);

                Vector3 direction = CalcAdjustIceFloorMoveDirection() * speed;
                int axis = IceFloorDirection.x != 0.0f ? 2 : 0;
                direction[axis] *= 2.0f;
                float moveLength = direction.FastNormalize() * deltaTime;

                CheckColSnowBall(direction, moveLength);
                bool isHit = CheckColIceFloor(direction, moveLength, out Vector3 outVelocity);

                float heightDiff = worldPosition.y - beforePosition.y;
                if (IsIceSlope)
                {
                    if (heightDiff * heightDiff < 0.001f * 0.001f)
                        IsIceSlope = false;
                }
                else
                {
                    int axis2 = IceFloorDirection.x != 0.0f ? 2 : 0;
                    float center = IceFloorStartGridCenterPos[axis2];
                    float current = worldPosition[axis2];
                    Vector3 before = beforePosition;
                    float prev = before[axis2];

                    if (heightDiff * heightDiff > 0.001f * 0.001f &&
                        (center - current) * (center - current) < 0.49f * 0.49f &&
                        (center - prev) * (center - prev) < 0.49f * 0.49f)
                    {
                        if (heightDiff < 0.0f)
                        {
                            if (IceSlidingLevel <= 3)
                                IceSlidingLevel = IceSlidingLevel + 1;
                        }
                        else
                        {
                            int level = IceSlidingLevel - 1;
                            if (level >= 0)
                                IceSlidingLevel = level;
                        }

                        IsIceSlope = true;
                    }
                }

                moveVector = outVelocity;

#if PC_UNLOCKED_FPS
                if ((worldPosition - beforePosition).sqrMagnitude < 0.001f * 0.001f * PcPlatform.PcFrameClock.Frames * PcPlatform.PcFrameClock.Frames) // PC (s37): "did not move" = under 0.001 per 30 Hz frame
#else
                if ((worldPosition - beforePosition).sqrMagnitude < 0.001f * 0.001f)
#endif
                    IceFloorStopTime += deltaTime;

                // IsIceGrid never reads its height argument
                if (!IsIceGrid(gridPosition, worldPosition.y) || IceFloorStopTime > 0.06f)
                {
                    AudioManager.Instance.PlaySe(AK.EVENTS.STOP_SE, null);
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI401, null);
                    EndIceFloor();
                }
                else if (IceSlidingLevel <= 0)
                {
                    CheckIceSlope();
                }

                if (IceFloorState == IceFloorStateType.Slip && isHit)
                {
                    AudioManager.Instance.PlaySe(AK.EVENTS.STOP_SE, null);
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI402, null);
                    EndIceFloor();
                }
                break;
            }
        }
    }
	private global::UnityEngine.Vector3 CalcAdjustIceFloorMoveDirection() {
        Vector3 adjust = Vector3.zero;
        int axis = IceFloorDirection.x != 0.0f ? 2 : 0;
        adjust[axis] = IceFloorStartGridCenterPos[axis] - worldPosition[axis];

        Vector3 direction = IceFloorDirection + adjust;
        direction.Normalize();
        return direction;
    }
	private void CheckColSnowBall(global::UnityEngine.Vector3 direction, float speed) {
        if (IceSlidingLevel < 2)
            return;

        var grid = PositionToGrid(worldPosition + direction * (speed + 0.5f));
        foreach (var entity in EntityManager.fieldObjects)
        {
            if (!entity.EventParams.SnowBall)
                continue;

            if (entity.gameObject != null && entity.gameObject.activeInHierarchy)
            {
                var entityGrid = entity.gridPosition;
                if (entityGrid.x == grid.x && entityGrid.y == grid.y)
                    CrashSnowBall(entity);
            }
        }
    }
	private void CrashSnowBall(global::FieldObjectEntity entity) {
        if (entity.EventParams.VanishFlagIndex < 1)
            return;

        EvDataManager.Instanse.SetFlag(entity.EventParams.VanishFlagIndex, true);
        entity.gameObject.SetActive(false);
        FieldManager.Instance.CallEffect(EffectFieldID.EF_F_BG_SNOWBALLBREAK_01, entity.transform, null, null);
        AudioManager.Instance.PlaySe(AK.EVENTS.S_FI112, null);
    }
	private bool CheckColIceFloor(global::UnityEngine.Vector3 direction, float speed, out global::UnityEngine.Vector3 outVelocity) {
        if (CheckColNpcIceFloor(direction, speed))
        {
            outVelocity = Vector3.zero;
            return true;
        }

        outVelocity = CollisionUtility.CollideObstacle(worldPosition, 0.4f, direction, speed, out bool jump, out bool isCollided, out float dotAngle,
            Layer.Jump | Layer.Obstacle);
        if (isCollided && dotAngle > 0.5f)
            return true;

        var velocity = direction * speed;
        if (FieldGridCollision.CheckGriCollisionMoveEntity(out outVelocity, worldPosition, velocity, 0.4f, CheckGridCollision,
            FieldGridCollision.GridCollisionIgnoreDir.None) != FieldGridCollision.GridCollisionType.None)
            return true;

        outVelocity = velocity;
        return false;
    }
	private bool CheckColNpcIceFloor(global::UnityEngine.Vector3 direction, float speed) {
        var grid = PositionToGrid(worldPosition + direction * (speed + 0.4f));
        for (int i = 0; i < EntityManager.fieldCharacters.Length; i++)
        {
            if (EntityManager.fieldCharacters[i] == EntityManager.activeFieldPlayer)
                continue;

            if (!EntityManager.fieldCharacters[i].gameObject.activeInHierarchy)
                continue;

            var entityGrid = EntityManager.fieldCharacters[i].gridPosition;
            if (entityGrid.x == grid.x && entityGrid.y == grid.y)
                return true;
        }

        return false;
    }
	private float UpdateIceSpeed(float deltaTime) {
        float targetSpeed = IceSlidingLevel < 1 ? 0.001f : DataManager.FieldCommonParam[(int)ParamIndx.IceFloorAcc + IceSlidingLevel].param;
        float accel = DataManager.FieldCommonParam[(int)ParamIndx.IceFloorAcc].param * deltaTime;
        float diff = IceSlidingSpeed - targetSpeed;
        if (!(diff * diff <= accel * accel))
            targetSpeed = diff > 0.0f ? IceSlidingSpeed - accel : IceSlidingSpeed + accel;

        IceSlidingSpeed = targetSpeed;
        return IceSlidingSpeed;
    }
	private void CheckIceSlope() {
        var slopeDir = CheckIceSlopeFloor();
        if (slopeDir == default(Vector2Int))
            return;

        var target = Vec2ToVec3Position(GridToPosition(gridPosition + slopeDir), worldPosition.y);
        int axis = IceFloorDirection.x != 0.0f ? 2 : 0;
        target[axis] = IceFloorStartGridCenterPos[axis];
        IceSlopeDownMove.MoveTime(target, 0.6f);
        IceFloorState = IceFloorStateType.SlopeDown;
    }
	private global::UnityEngine.Vector2Int CheckIceSlopeFloor() {
        var center = Vec2ToVec3Position(GridToPosition(gridPosition), worldPosition.y);
        center.y += CollisionUtility.CollideGround(center, 30.0f, Layer.Ground);

        float height = CollisionUtility.CollideGround(center + Vector3.right * 0.05f, 30.0f, Layer.Ground);
        if (height * height > 0.0001f)
            return height > 0.0f ? Vector2Int.right : Vector2Int.left;

        height = CollisionUtility.CollideGround(center + Vector3.left * 0.05f, 30.0f, Layer.Ground);
        if (height * height > 0.0001f)
            return height > 0.0f ? Vector2Int.left : Vector2Int.right;

        height = CollisionUtility.CollideGround(center + Vector3.forward * 0.05f, 30.0f, Layer.Ground);
        if (height * height > 0.0001f)
            return height > 0.0f ? Vector2Int.down : Vector2Int.up;

        height = CollisionUtility.CollideGround(center + Vector3.back * 0.05f, 30.0f, Layer.Ground);
        if (height * height > 0.0001f)
            return height > 0.0f ? Vector2Int.up : Vector2Int.down;

        return default;
    }
