	public bool CheckSwim() {
        if (!FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.BADGE_ID_C05))
            return false;

        var direction = CalcCheckFrontGridDirection();
        var frontGrid = PositionToGrid(worldPosition + direction * NaminoriCheckDistance);
        if (frontGrid.x != gridPosition.x && frontGrid.y != gridPosition.y)
            return false;

        GameManager.GetAttribute(frontGrid, out int code, out int stop);
        var table = GameManager.GetAttributeTable(code);
        if (table != null && !table.Water)
            return false;

        if (AttributeID.MATR_IsBridgeWater(code) && GameManager.IsHighAttribute(GameManager.GetAttributeExCodeRaw(frontGrid), worldPosition.y))
            return false;

        var velocity = CollisionUtility.CollideObstacle(worldPosition, 0.4f, direction, NaminoriCheckDistance, out bool jump, out bool isCollided,
            out float dotAngle, Layer.Obstacle);
        if (isCollided)
            return false;

        return FieldGridCollision.CheckGriCollisionMoveEntity(out Vector3 outVelocity, worldPosition, velocity, 0.4f, CheckGridCollisionCheckSwim,
            FieldGridCollision.GridCollisionIgnoreDir.None) == FieldGridCollision.GridCollisionType.None;
    }
