	public global::UnityEngine.Vector3 CalcSwimTargetPosition() {
        var direction = CalcCheckFrontGridDirection();
        var frontPos = worldPosition + direction * NaminoriCheckDistance;
        var frontGrid = PositionToGrid(frontPos);
        var targetPos = Vec2ToVec3Position(GridToPosition(frontGrid), frontPos.y);

        var startPos = frontPos;
        if (gridPosition.x != frontGrid.x)
            startPos.x = targetPos.x;
        else if (gridPosition.y != frontGrid.y)
            startPos.z = targetPos.z;

        if (ZoneWork.IsUnderGround(PlayerWork.zoneID))
            targetPos.y = -0.5f;
        else
            targetPos.y += CollisionUtility.CollideGround(targetPos, 0.5f, Layer.Ground);

        var moveVec = startPos - targetPos;
        moveVec.y = 0.0f;
        float length = moveVec.magnitude;
        if (!(length < 0.0001f))
        {
            var velocity = CollisionUtility.CollideObstacle(targetPos, 0.4f, moveVec.normalized, length, out bool jump, out bool isCollided,
                out float dotAngle, Layer.Obstacle);
            CheckGridCollisionCalcSwim.waterPositionY = frontPos.y;

            if (FieldGridCollision.CheckGriCollisionMoveEntity(out Vector3 outVelocity, targetPos, velocity, 0.4f, CheckGridCollisionCalcSwim,
                FieldGridCollision.GridCollisionIgnoreDir.None) == FieldGridCollision.GridCollisionType.None)
                targetPos += velocity;
            else if (!isCollided)
                targetPos += outVelocity;
        }

        return new Vector3(targetPos.x, targetPos.y + NaminoriWaterSurfaceOfs, targetPos.z);
    }
