	private bool UpdateSwim(float deltaTime) {
        Vector2 stick = GameController.analogStickL;
        if (stick.x * stick.x + stick.y * stick.y < 0.01f)
            stick = GameController.digitalPad;

        if (stick.x * stick.x + stick.y * stick.y > 0.01f)
        {
            if (CheckEndSwim(stick))
            {
                RequestEndSwimEvent();
                return true;
            }

            if (CheckWaterfallDown(stick))
            {
                WaterfallDownEvent();
                return true;
            }
        }

        if (FieldInput.PushA() && CheckWaterfallUp())
        {
            WaterfallUpEvent();
            return true;
        }

        return false;
    }
	private bool CheckEndSwim(global::UnityEngine.Vector2 inputDir) {
        var direction = CalcCheckFrontGridDirection();
        var input = new Vector3(-inputDir.x, 0.0f, -inputDir.y);
        // 0.9396926f = cos(20 deg) (0x3f708fb2 @01db3098)
        if (Vector3.Dot(input, direction) < 0.9396926f)
            return false;

        var frontGrid = PositionToGrid(worldPosition + direction * NaminoriCheckDistance);
        if (frontGrid.x != gridPosition.x && frontGrid.y != gridPosition.y)
            return false;

        GameManager.GetAttribute(frontGrid, out int code, out int stop);
        bool isBridgeWater = AttributeID.MATR_IsBridgeWater(code);

        GameManager.GetAttribute(frontGrid, out int landCode, out int landStop);
        if (!CanEntryAttributeCommon(landCode, landStop))
            return false;

        var table = GameManager.GetAttributeTable(landCode);
        if (table != null && table.Water)
            return false;

        if (isBridgeWater && AttributeID.MATR_IsBridge(landCode))
            return false;

        var velocity = CollisionUtility.CollideObstacle(worldPosition, 0.4f, direction, NaminoriCheckDistance, out bool jump, out bool isCollided,
            out float dotAngle, Layer.Obstacle);
        if (isCollided)
            return false;

        return FieldGridCollision.CheckGriCollisionMoveEntity(out Vector3 outVelocity, worldPosition, velocity, 0.4f, CheckGridCollisionEndSwim,
            FieldGridCollision.GridCollisionIgnoreDir.None) == FieldGridCollision.GridCollisionType.None;
    }
