	public bool CheckRockClimbing(global::FieldObjectEntity eventObject) {
        var forward = transform.forward;
        forward.y = 0.0f;
        forward = forward.normalized;

        var direction = CalcRockClimbingDirection(eventObject);
        if (direction.x != 0.0f)
        {
            if (Mathf.Abs(forward.x) < 0.819152f)
                return false;

            var eventGrid = eventObject.gridPosition;
            if (eventGrid.y != gridPosition.y)
                return false;

            return !(direction.x * (eventGrid.x - gridPosition.x) > 0.0f);
        }
        else if (direction.z != 0.0f)
        {
            if (Mathf.Abs(forward.z) < 0.819152f)
                return false;

            var eventGrid = eventObject.gridPosition;
            if (eventGrid.x != gridPosition.x)
                return false;

            return !(direction.z * (eventGrid.y - gridPosition.y) < 0.0f);
        }

        return true;
    }
	public void CalcRockClimbingTargetPosition(global::FieldObjectEntity eventObject, out global::UnityEngine.Vector3 climbStart, out global::UnityEngine.Vector3 climbEnd, out global::UnityEngine.Vector3 standPos) { /*@B 0x60007C8*/ throw null; }
	public global::UnityEngine.Vector3 CalcRockClimbingAnotherTalkPosition(global::FieldObjectEntity eventObject) {
        var position = eventObject.worldPosition;
        var direction = CalcRockClimbingDirection(eventObject);
        if (direction.x == 0.0f)
            position.z += eventObject.EventParams.ContactSize.y + -1.0f;
        else
            position.x -= eventObject.EventParams.ContactSize.x + -1.0f;

        return position;
    }
	private global::UnityEngine.Vector3 CalcRockClimbingDirection(global::FieldObjectEntity eventObject) {
        var forward = transform.forward;
        forward.y = 0.0f;
        forward = forward.normalized;

        var size = eventObject.EventParams.ContactSize;
        bool isVertical;
        if (Mathf.Abs(size.x - size.y) < 0.1f)
            isVertical = Mathf.Abs(forward.x) < Mathf.Abs(forward.z);
        else
            isVertical = size.x < size.y;

        if (isVertical)
            return new Vector3(0.0f, 0.0f, forward.z > 0.0f ? 1.0f : -1.0f);
        else
            return new Vector3(forward.x > 0.0f ? 1.0f : -1.0f, 0.0f, 0.0f);
    }
