        }
    }
	private bool CheckSwampDeep(float deltaTime) {
        if (currentSequence != SequenceID.Active || !PlayerWork.isPlayerInputActive)
            return false;

        if (gridPosition == oldGridPosition)
            return false;

        // IsSwampDeepGrid never reads its height argument
        return IsSwampDeepGrid(gridPosition, worldPosition.y);
    }
	private void StartSwampDeep() {
        PlayerWork.isPlayerInputActive = false;
        SwampPhase = SwampPhaseType.Start;
        SwampDeepInputDir = DIR.DIR_NOT;
        SwampDeepInputCount = 0;
        SwampWait.MoveTime(1.0f, DataManager.FieldCommonParam[(int)ParamIndx.SwampDeep_AdjustWaitTime].param);
        SwampMove.FloatMove.EaseFunc = FieldFloatMove.EaseInOutSin;
        SwampMove.IgnoreY = true;
        SwampMove.SetObjectEntity(this);
        isPlayedSwampStartEffect = false;
        _animationPlayer.Play(Animation.SwampStart, 0.2f);
        nextSequence = SequenceID.SwampDeep;
    }
	private void EndSwampDeep() {
        PlayerWork.isPlayerInputActive = true;
        SwampMove.Reset();
        PlayIdle();
        StopCrossUpdate();
        nextSequence = SequenceID.Active;
    }
	private void UpdateSwampDeep(float deltaTime) {
        SwampWait.Update(deltaTime);
        SwampMove.Update(deltaTime);

        switch (SwampPhase)
        {
            case SwampPhaseType.Start:
                if (SwampWait.IsBusy)
                {
                    if (!isPlayedSwampStartEffect && SwampWait.CurrentTime > 0.1f)
                    {
                        isPlayedSwampStartEffect = true;
                        AudioManager.Instance.PlaySe(AK.EVENTS.S_FI216, null);
                        FieldManager.Instance.CallEffect(EffectFieldID.EF_F_CHARA_SWAMP_SINK, transform, null, null);
                    }
                }
                else
                {
                    var current = worldPosition;
                    var target = Vec2ToVec3Position(GridToPosition(gridPosition), worldPosition.y);

                    var sideGrid = gridPosition;
                    sideGrid.x += target.x < worldPosition.x ? -1 : 1;
                    if (IsSwampDeepGrid(sideGrid, worldPosition.y))
                        target.x = current.x;

                    var frontGrid = gridPosition;
                    frontGrid.y += !(target.z < worldPosition.z) ? -1 : 1;
                    if (IsSwampDeepGrid(frontGrid, worldPosition.y))
                        target.z = current.z;

                    SwampMove.MoveTime(new Vector3(target.x, current.y, target.z), DataManager.FieldCommonParam[(int)ParamIndx.SwampDeep_AdjustMoveTime].param);
                    SwampPhase = SwampPhaseType.Start_Move;
                }
                break;

            case SwampPhaseType.Start_Move:
                if (_animationPlayer.IsPlayingEnd && !SwampMove.IsBusy)
                {
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI219, null);
                    _animationPlayer.Play(Animation.SwampLoop, 0.2f);
                    SwampPhase = SwampPhaseType.Loop;
                }
                break;

            case SwampPhaseType.Loop:
            {
                GetInputVectorIgnoreUpdateInputAngle(out Vector2 stickL, out float stickPowerSq, deltaTime, out bool analogstick);

                if (!isSwampLoopEffect)
                {
                    isSwampLoopEffect = true;
                    FieldManager.Instance.CallEffect(EffectFieldID.EF_F_CHARA_SWAMP_STRUGGLE, transform, null, instance => isSwampLoopEffect = false);
                }

                if (stickPowerSq > 0.01f)
                {
                    DIR inputDir;
                    if (Mathf.Abs(stickL.x) < Mathf.Abs(stickL.y))
                        inputDir = stickL.y > 0.0f ? DIR.DIR_UP : DIR.DIR_DOWN;
                    else
                        inputDir = stickL.x > 0.0f ? DIR.DIR_RIGHT : DIR.DIR_LEFT;

                    if (inputDir != SwampDeepInputDir)
                    {
                        SwampDeepInputDir = inputDir;
                        SwampDeepInputCount++;

                        if (SwampDeepInputCount < (int)DataManager.FieldCommonParam[(int)ParamIndx.SwampDeep_InputCount].param)
                        {
                            AudioManager.Instance.PlaySe(AK.EVENTS.S_FI219, null);
                        }
                        else
                        {
                            AudioManager.Instance.PlaySe(AK.EVENTS.S_FI005, null);
                            AudioManager.Instance.PlaySe(AK.EVENTS.S_FI219_2, null);
                            FieldManager.Instance.CallEffect(EffectFieldID.EF_F_CHARA_SWAMP_ESCAPE, transform, null, null);
                            _animationPlayer.Play(Animation.SwampEnd, 0.2f);
                            SwampPhase = SwampPhaseType.End;
                        }
                    }
                }
                break;
            }

            case SwampPhaseType.End:
                if (_animationPlayer.IsPlayingEnd)
                    EndSwampDeep();
                break;
        }
    }
	private bool IsSwampDeepGrid(global::UnityEngine.Vector2Int grid, float height) { /*@B 0x60007D1*/ throw null; }
	private bool CheckWaterfallDown(global::UnityEngine.Vector2 inputDir) {
        var direction = CalcCheckFrontGridDirection();
        if (direction.z < 0.0f)
            return false;

        var input = new Vector3(-inputDir.x, 0.0f, -inputDir.y);
        // 0.9396926f = cos(20 deg) (0x3f708fb2)
        if (Vector3.Dot(input, direction) < 0.9396926f)
            return false;

        var frontGrid = PositionToGrid(worldPosition + direction * WaterFallDownCheckDistance);
        if (frontGrid.x != gridPosition.x && frontGrid.y != gridPosition.y)
            return false;

        GameManager.GetAttribute(frontGrid, out int code, out int stop);
        return AttributeID.MATR_IsWaterFall(code);
    }
	public global::UnityEngine.Vector3 CalcWaterfallDownTargetPosition() {
        var direction = CalcCheckFrontGridDirection();
        var grid = PositionToGrid(worldPosition + direction * WaterFallDownCheckDistance);
        grid.y += 1;

        var position = Vec2ToVec3Position(GridToPosition(grid), worldPosition.y);
        float height = position.y + CollisionUtility.CollideGround(position, 0.0f, Layer.Ground) + NaminoriWaterSurfaceOfs;
        return new Vector3(worldPosition.x, height, position.z);
    }
	public bool CheckWaterfallUp() {
        var direction = CalcCheckFrontGridDirection();
        if (direction.z > 0.0f)
            return false;

        var frontGrid = PositionToGrid(worldPosition + direction * WaterFallUpCheckDistance);
        if (frontGrid.x != gridPosition.x && frontGrid.y != gridPosition.y)
            return false;

        GameManager.GetAttribute(frontGrid, out int code, out int stop);
        return AttributeID.MATR_IsWaterFall(code);
    }
	public global::UnityEngine.Vector3 CalcWaterfallUpTargetPosition() {
        var direction = CalcCheckFrontGridDirection();
        var grid = PositionToGrid(worldPosition + direction * WaterFallUpCheckDistance);
        grid.y -= 1;

        var position = Vec2ToVec3Position(GridToPosition(grid), worldPosition.y);
        float height = position.y + CollisionUtility.CollideGround(position, 30.0f, Layer.Ground) + NaminoriWaterSurfaceOfs;
        return new Vector3(worldPosition.x, height, position.z);
    }
